args:
set -euo pipefail
cp /app/scripts/glitch/run-glitch-local-game-stack-v92.sh /tmp/run-glitch-local-game-stack-no-chat-gate.sh
node <<'NODE_PATCH'
const fs = require("fs");
const path = "/tmp/run-glitch-local-game-stack-no-chat-gate.sh";
let s = fs.readFileSync(path, "utf8");
const old = "wait_http_ready 127.0.0.1 3301 chat\nwait_redis_stream_group 4 chat-delivery redis-chat-distributor chat-distributor\n";
const requireExpr = "$" + "{GLITCH_REQUIRE_CHAT_READY:-0}";
const replacement = [
  'if [ "' + requireExpr + '" = "1" ]; then',
  '  wait_http_ready 127.0.0.1 3301 chat',
  '  wait_redis_stream_group 4 chat-delivery redis-chat-distributor chat-distributor',
  'else',
  '  log "WARN chat readiness bypassed for game rollout; debugging chat separately"',
  'fi',
].join("\n") + "\n";
if (!s.includes(old)) {
  throw new Error("chat readiness block not found in runner");
}
fs.writeFileSync(path, s.replace(old, replacement));
NODE_PATCH
chmod +x /tmp/run-glitch-local-game-stack-no-chat-gate.sh
exec /tmp/run-glitch-local-game-stack-no-chat-gate.sh
